window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-41a859aff6698385"]={"versions": [{"id": "FIG-41a859aff6698385", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout (Protokoll-Header-Format) im Kontext des AUTOSAR E2E (End-to-End) Protocol für E2E Profile 4. Das Diagramm spezifiziert die Serialisierung und Bit- bzw. Byte-Anordnung der Schutzfelder innerhalb eines 12-Byte (96-Bit) großen E2E-Headers zur Absicherung sicherheitsrelevanter Datenübertragungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die Struktur des E2E Profile 4 Headers mit einer Breite von 32 Bit (4 Byte pro Zeile) und einem Gesamtrahmen von 12 Byte:</p>\n<ul class=\"fig-list\"><li>Spaltenköpfe / Übertragungsordnung: Byte-Indizes 0, 1, 2, 3 und Bit-Indizes 0 bis 31 („Transmission order“).\n</li><li>Zeile Offset 0 (Byte 0–3):\n<ul class=\"fig-list\"><li><code>E2E Length</code>: 16 Bit (Bit 0 bis 15, Byte 0 und 1).\n</li><li><code>E2E Counter</code>: 16 Bit (Bit 16 bis 31, Byte 2 und 3).\n</li></ul>\n</li><li>Zeile Offset 4 (Byte 4–7):\n<ul class=\"fig-list\"><li><code>E2E Data ID</code>: 32 Bit (Bit 0 bis 31, Byte 4 bis 7).\n</li></ul>\n</li><li>Zeile Offset 8 (Byte 8–11):\n<ul class=\"fig-list\"><li><code>E2E CRC</code>: 32 Bit (Bit 0 bis 31, Byte 8 bis 11).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicher- und Übertragungslayout ohne zeitliche Ablauflogik. Bei der Übertragung werden die Felder sequenziell gemäß Transmission Order übermittelt: Beginnend bei Byte-Offset 0 mit <code>E2E Length</code> (Byte 0–1), gefolgt vom <code>E2E Counter</code> (Byte 2–3), der 32-Bit <code>E2E Data ID</code> (Byte 4–7) und abschließend der 32-Bit <code>E2E CRC</code> (Byte 8–11). Alle Felder sind lückenlos in 32-Bit-Wörtern angeordnet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Bit- und Byte-Mapping für die Implementierung der E2E-Profile-4-Schutzschicht im E2E-Modul bzw. E2E-Transformer. Entwickler müssen die definierte Feldlänge und Reihenfolge exakt einhalten: 16 Bit Länge, 16 Bit Alive-Counter, 32 Bit Data-ID und 32 Bit Prüfsumme (CRC-32). Abweichende Serialisierungen, Offsets oder Byte-Reihenfolgen führen zu Inkompatibilitäten und CRC-Prüffehlern auf Empfängerseite.</p>"}, {"id": "FIG-c9fd0c820a84a75b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout (Protokoll-Header-Format) im Kontext des AUTOSAR E2E (End-to-End) Protocol für E2E Profile 4. Das Diagramm spezifiziert die Serialisierung und Bit- bzw. Byte-Anordnung der Schutzfelder innerhalb eines 12-Byte (96-Bit) großen E2E-Headers zur Absicherung sicherheitsrelevanter Datenübertragungen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist die Struktur des E2E Profile 4 Headers mit einer Breite von 32 Bit (4 Byte pro Zeile) und einem Gesamtrahmen von 12 Byte:</p>\n<ul class=\"fig-list\"><li>Spaltenköpfe / Übertragungsordnung: Byte-Indizes 0, 1, 2, 3 und Bit-Indizes 0 bis 31 („Transmission order“).\n</li><li>Zeile Offset 0 (Byte 0–3):\n<ul class=\"fig-list\"><li><code>E2E Length</code>: 16 Bit (Bit 0 bis 15, Byte 0 und 1).\n</li><li><code>E2E Counter</code>: 16 Bit (Bit 16 bis 31, Byte 2 und 3).\n</li></ul>\n</li><li>Zeile Offset 4 (Byte 4–7):\n<ul class=\"fig-list\"><li><code>E2E Data ID</code>: 32 Bit (Bit 0 bis 31, Byte 4 bis 7).\n</li></ul>\n</li><li>Zeile Offset 8 (Byte 8–11):\n<ul class=\"fig-list\"><li><code>E2E CRC</code>: 32 Bit (Bit 0 bis 31, Byte 8 bis 11).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Speicher- und Übertragungslayout ohne zeitliche Ablauflogik. Bei der Übertragung werden die Felder sequenziell gemäß Transmission Order übermittelt: Beginnend bei Byte-Offset 0 mit <code>E2E Length</code> (Byte 0–1), gefolgt vom <code>E2E Counter</code> (Byte 2–3), der 32-Bit <code>E2E Data ID</code> (Byte 4–7) und abschließend der 32-Bit <code>E2E CRC</code> (Byte 8–11). Alle Felder sind lückenlos in 32-Bit-Wörtern angeordnet.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Bit- und Byte-Mapping für die Implementierung der E2E-Profile-4-Schutzschicht im E2E-Modul bzw. E2E-Transformer. Entwickler müssen die definierte Feldlänge und Reihenfolge exakt einhalten: 16 Bit Länge, 16 Bit Alive-Counter, 32 Bit Data-ID und 32 Bit Prüfsumme (CRC-32). Abweichende Serialisierungen, Offsets oder Byte-Reihenfolgen führen zu Inkompatibilitäten und CRC-Prüffehlern auf Empfängerseite.</p>"}], "trans": [{"from": "FIG-41a859aff6698385", "to": "FIG-c9fd0c820a84a75b", "fr": "R19-03", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
